  ('8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पी.टी. प्रीतमचंद के तोतों की देखभाल के तरीके से उनके किस मानवीय पक्ष का पता चलता है, जो छात्रों के प्रति उनके व्यवहार से मेल नहीं खाता?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यदि आप उन छात्रों में से एक होते, तो पी.टी. प्रीतमचंद के दोहरे व्यवहार पर आपकी क्या प्रतिक्रिया होती और आप उसे कैसे समझने का प्रयास करते?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true);
