  ('38e0397c-e1b7-483b-9168-904e30c5bba5', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे साथ खेलने वाले सभी बच्चों का हाल एक-सा होता। नंगे पाँव, फटी-मैली सी कच्छी और टूटे बटनों वाले कई जगह से फटे कुर्ते और बिखरे बाल।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('8367efd1-8850-42fb-9ba4-6f7ea6fddb03', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब लकड़ी के ढेर पर चढ़कर खेलते नीचे को भागते तो गिरकर कई तो जाने कहाँ-कहाँ चोट खा लेते और पहले ही फटे-पुराने कुर्ते तार-तार हो जाते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('aa30eb83-d6d7-40fe-9b25-c7ce3b235a66', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$धूल भरे, कई जगह से छिपे पाँव, पिंडलियाँ या लहू के ऊपर जमी रेत-मिट्टी से लथपथ घुटने लेकर जाते तो सभी की माँ-बहनें उन पर तरस खाने की जगह और पिटाई करतीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('9d1d4fe2-98d3-48ff-b732-6c708b3b99a5', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कईयों के बाप बड़े गुस्सैल थे। पीटने लगते तो यह ध्यान भी न रखते कि छोटे बच्चे के नाक-मुँह से लहू बहने लगा है या उसके कहाँ चोट लगी है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('42b95454-6dfb-4e0f-ab99-92ae6e8d85ef', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु इतनी बुरी पिटाई होने पर भी दूसरे दिन फिर खेलने चले आते। (यह बात तब ठीक से समझ आई जब स्कूल अध्यापक बनने के लिए एक ट्रेनिंग करने गया और वहाँ बाल-मनोविज्ञान का विषय पढ़ा।)$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('77935cdc-d883-40a3-9dd6-edc4a42d90b5', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ऐसी बातों के बारे में तभी जान पाया कि बच्चों को खेलना क्यों इतना अच्छा लगता है कि बुरी तरह पिटाई होने पर भी फिर खेलने चले आते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('f3083f74-1783-4922-95e5-b6b17eea0fb1', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे साथ खेलने वाले अधिकतर साथी हमारे जैसे ही परिवारों के हुआ करते। सारे मुहल्ले में बहुत परिवार तो, हमारी तरह आसपास के गाँवों से ही आकर बसे थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('e9973489-a069-48d6-ba00-2dfac43e885f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनमें से अधिक तो स्कूल जाते ही न थे, जो कभी गए भी, पढ़ाई में रुचि न होने के कारण किसी दिन बस्ता तालाब में फेंक आए और फिर स्कूल गए ही नहीं, न ही माँ-बाप ने ज़बरदस्ती भेजा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('d2e83cca-ae27-47f2-96ba-8ff997dc6dc8', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यहाँ तक कि पर्चूनिए, आढ़तिए भी अपने बच्चों को स्कूल भेजना ज़रूरी न समझते। कभी किसी स्कूल अध्यापक से बात होती तो कहते—मास्टर जी हमने इसे क्या तहसीलदार लगवाना है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('03fd2bcd-2365-41ba-851d-cead3bbbaba3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$थोड़ा बड़ा हो जाए तो पंडित घनश्याम दास से लंडे पढ़वाकर दुकान पर बहियाँ लिखने लगा लेंगे। पंडित छह-आठ महीने में लंडे और मुनीमी का सभी काम सिखा देगा। वहाँ तो अभी तक अलिफ़-बे जीम-चे भी सीख नहीं पाया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('c1b87898-4c4a-4cbc-86fa-ed68ef36a3a7', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे आधे से अधिक साथी राजस्थान या हरियाणा से आकर मंडी में व्यापार या दुकानदारो करते आए परिवारों से थे। जब बहुत छोटे थे तो उनकी बोली कम समझ पाते। उनके कुछ शब्द सुनकर हमें हँसी आने लगती। परंतु खेलते तो सभी एक-दूसरे की बात खूब अच्छी तरह समझ लेते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f7100a75-0012-4443-af8b-010ba78128de', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बचपन में घास अधिक हरी और फूलों की सुगंध अधिक मनमोहक लगती है। यह शब्द शायद आधी सदी पहले किसी पुस्तक में पढ़े थे, परंतु आज तक याद हैं। याद रहने का कारण यही है कि यह वाक्य बचपन की भावनाओं, सोच-समझ के अनुकूल होगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ea1e5c1a-7e6a-4119-93bb-4ce3227d2cea', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु स्कूल के अंदर जाने से रास्ते के दोनों ओर जो अलियार के बड़े ढंग से कटे-छंटे झाड़ उगे थे (जिन्हें हम मंडियाँ कहा करते) उनके नीम के पत्तों जैसे पत्तों की महक आज तक भी आँख मूँदकर महसूस कर सकता हूँ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('94247db0-f843-4ce9-a205-b96174fc9ae5', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन दिनों स्कूल की छोटी क्यारियों में फूल भी कई तरह के उगाए जाते थे जिनमें गुलाब, गेंदा और मोतिया की दूध-सी सफेद कलियाँ भी हुआ करतीं। ये कलियाँ इतनी सुंदर और खुशबूदार होती थीं कि हम चंदू चपरासी से आँख बचाकर कभी-कभार एक-दो तोड़ लिया करते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d9e35f91-5cab-45cd-8bf6-a490b2a4a296', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनकी बहुत तेज़ सुगंध आज भी महसूस कर पाता हूँ, परंतु यह याद नहीं कि उन्हें तोड़कर, कुछ देर सूँघकर फिर क्या किया करते। (शायद जेब में डाल लेते, माँ उसे धोने के समय निकालकर बाहर फेंक देती या हम ही, स्कूल से बाहर आते उन्हें बकरी के मेमनों की भाँति 'चर' जाया करते)।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('1e5ebdf0-ee21-4d9c-aba9-79204b0bbeae', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब अगली श्रेणी में दाख़िल होते तो एक ओर तो कुछ बड़े, सयाने होने के एहसास से उत्साहित भी होते, परंतु दूसरी ओर नई, पुरानी कॉपियों-किताबों से जाने कैसी बास आती कि उन्हीं मास्टरों के डर से काँपने लगते जो पिछली श्रेणी में पढ़ा चुके होते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('c0d7caaa-86de-4281-83ae-ebbbed7877e8', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तब स्कूल में, शुरू साल में एक-डेढ़ महीना पढ़ाई हुआ करती, फिर डेढ़-दो महीने की छुट्टियाँ शुरू हो जाया करतीं। अब तक जो बात अच्छी तरह याद है वह छुट्टियों के पहले और आखिरी दिनों का फ़र्क था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('03cd347c-e8f8-480a-8f4f-15e603d91aa3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पहले दो-तीन सप्ताह तो खूब खेल-कूद हुआ करती। हर साल ही माँ के साथ नानीहाल चले जाते। वहाँ नानी खूब दूध-दही, मक्खन खिलाती, बहुत प्यार करती। छोटा सा पिछड़ा गाँव था परंतु तालाब हमारी मंडी के तालाब जितना ही बड़ा था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('0afdde3c-a9ca-48b2-aa90-33edfd13e573', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोपहर तक तो उस तालाब में नहाते फिर नानी से जो जी में आता माँगकर खाने लगते। नानी हमारे बोलने के ढंग या कम खाने के कारण बहुत खुश होती। अपने पोतों को हमारी तरह बोलने और खाने-पीने को कहती।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('dde89808-b1d7-4da3-840b-97aa0b92fe80', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जिस साल नानीहाल न जा पाते, उस साल भी अपने घर से थोड़ा बाहर तालाब पर चले जाते। कपड़े उतार पानी में कूद जाते और कुछ समय बाद, भागते हुए एक रेतीले टीले पर जाकर, रेत के ऊपर लेटने लगते। गीले शरीर।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('1ed83774-875f-4304-9c31-f51bbc1befb4', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारा स्कूल बहुत छोटा था—केवल छोटे-छोटे नौ कमरे थे जो अंग्रेजी के अक्षर एच (H) की भांति बने थे। दाईं ओर पहला कमरा हेडमास्टर श्री मदनमोहन शर्मा जी का था जिसके दरवाजे के आगे हमेशा चिक लटकी रहती।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('84186fbe-cc1c-4574-b53a-dd1c7973998d', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$स्कूल की प्रेयर (प्रार्थना) के समय वह बाहर आते और सीधी कतारों में कद के अनुसार खड़े लड़कों को देख उनका गोरा चेहरा खिल उठता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
