  ('df760b50-af21-40d0-b527-ae78e40aee44', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनकी घुड़की तथा ठुंसों के भय से हम सभी कतार के पहले और आखिरी लड़के का ध्यान रखते, सीधे कतार में बने रहने का प्रयत्न करते। सीधी कतार के साथ-साथ हमें यह ध्यान भी रखना होता था कि आगे पीछे खड़े लड़कों के बीच की दूरी भी एक सी हो।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('908b38ac-5b23-4387-9b69-43c588a0e1da', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु हेडमास्टर शर्मा जी उसके बिल्कुल उलट स्वभाव के थे। वह पाँचवीं और आठवीं श्रेणी को अंग्रेजी स्वयं पढ़ाया करते थे। हमारे में से किसी को भी याद न था कि पाँचवीं श्रेणी में कभी भी उन्हें, किसी गलती के कारण किसी की 'चमड़ी उधेड़ते' देखा या सुना हो।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('235acecb-795b-4735-8923-a962482359e0', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$(चमड़ी उधेड़ना हमारे लिए बिल्कुल ऐसा शब्द था जैसे हमारे 'सरकारी मिडिल स्कूल' का नाम।) अधिक से अधिक वह गुस्से में बहुत जल्दी-जल्दी आँखें झपकते, अपने लंबे हाथ की उल्टी उँगलियों से एक 'चपत' हमारी गाल पर मार देते तो मेरे जैसे सबसे कमज़ोर शरीर वाले भी सिर झुकाकर मुँह नीचा किए हँस देते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4dd3a416-348f-4962-b1c6-b27634e83fc2', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह चपत तो जैसे हमें भाई भीखे की नमकीन पापड़ी जैसी मज़ेदार लगती जो तब पैसे की शायद दो आ जाया करतीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5d1c75c3-5025-4dde-980e-3cd55841c601', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु तब भी स्कूल हमारे लिए ऐसी जगह न थी जहाँ खुशी से भागे जाएँ। पहली कच्ची श्रेणी से लेकर चौथी श्रेणी तक, केवल पाँच-सात लड़कों को छोड़ हम सभी रोते चिल्लाते ही स्कूल जाया करते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('84525925-8a26-4489-9ace-3613ac2b96e3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु कभी-कभी ऐसी सभी स्थितियों के रहते स्कूल अच्छा भी लगने लगता। जब स्काउटिंग का अभ्यास करवाते समय पीटी साहब नीली-पीली झंडियाँ हाथों में पकड़ाकर वन टू थ्री कहते, झंडियाँ ऊपर-नीचे, दाएँ-बाएँ करवाते तो हवा में लहराती और...$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
