  ('5fca2406-4d92-4d05-aa60-4215bc628ba5', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे में से किसी को भी याद न था कि पाँचवीं श्रेणी में कभी भी उन्हें, किसी गलती के कारण किसी की 'चमड़ी उधेड़ते' देखा या सुना हो।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
