  ('fce38aeb-eb8b-4b28-9b70-ff6d726dd02a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पहली कच्ची श्रेणी से लेकर चौथी श्रेणी तक, केवल पाँच-सात लड़कों को छोड़ हम सभी रोते चिल्लाते ही स्कूल जाया करते। परंतु कभी-कभी ऐसी सभी स्थितियों के रहते स्कूल अच्छा भी लगने लगता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9e3c984b-5c2b-4b67-bafd-d05790b3c804', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पी.टी. साहब अपनी चमकीली आँखें हल्के से झपकाते कहते—'शाबाश! वैल बिगिन अगेन—वन, टू, थ्री, थ्री, टू, वन!' उनकी एक शाबाश ऐसे लगने लगती जैसे हमने किसी फौज के सभी तमगे जीत लिए हों। कभी यही एक शाबाश, सभी मास्टरों की ओर से, हमारी सभी कापियों पर साल भर की लिखी 'गुंओं' (गुड का बहुवचन) से अधिक मूल्यवान लगने लगती।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('0a5a8d37-28da-49ac-a1a9-736de15c91d3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु यह भी एहसास रहता कि जैसे गुरुद्वारे का भाई जी कथा करते समय बताया करता कि सतगुरु के भय से ही प्रेम जागता है, ऐसे ही पी.टी. साहब के प्रति हमारी प्रेम की भावना जग जाती। (यह ऐसा भी है कि आपको रोष फटकारने वाला कोई 'अपना' यदि साल भर के बाद एक बार 'शाबाश' कह दे तो यह चमत्कार-सा लगने लगता है—हमारी दशा भी कुछ ऐसी हुआ करती।)$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d0ec1d5b-f78e-40dd-b38d-572ab60a48b7', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हर वर्ष अगली श्रेणी में प्रवेश करते समय मुझे पुरानी पुस्तकें मिला करतीं। हमारे हेडमास्टर शर्मा जी एक लड़के को उसके घर जाकर पढ़ाया करते थे। वे धनाढ्य लोग थे। उनका लड़का मुझसे एक-दो साल बड़ा होने के कारण मेरे से एक श्रेणी आगे रहा। हर साल अप्रैल में जब पढ़ाई का नया साल आरंभ होता तो शर्मा जी उसकी एक साल पुरानी पुस्तकें ले आते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('1729d2ca-2d3d-4591-a51c-0cd3e98ffa34', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे घर में किसी को भी पढ़ाई में दिलचस्पी न थी। यदि नई किताबें लानी पड़तीं (जो तब एक-दो रुपये में आ जाया करतीं) तो शायद इसी बहाने पढ़ाई तीसरी-चौथी श्रेणी में ही छूट जाती। कोई सात साल स्कूल में रहा तो एक कारण पुरानी किताबें मिल जाना भी था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('060e362d-ec5f-418e-b466-4dcf58909a05', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कॉपियों, पेंसिलों, होल्डर या स्याही-दवात में भी मुश्किल से एक-दो रुपये साल भर में खर्च हुआ करते। परंतु उस जमाने में एक रुपया भी बहुत बड़ी 'रकम' हुआ करती थी। एक रुपये में एक सेर घी आया करता और दो रुपये की एक मन (चालीस सेर) गंदम।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a7530020-8ebd-482b-9540-7b84dd7214bd', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसी कारण, खाते-पीते घरों के लड़के ही स्कूल जाया करते। हमारे दो परिवारों में मैं पहला लड़का था जो स्कूल जाने लगा था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('5c91406d-52b6-4c4d-90d7-05658777a492', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु किसी भी नई श्रेणी में जाने का ऐसा चाव कभी भी महसूस नहीं हुआ जिसका जिक्र कुछ लड़के किया करते। अजीब बात थी कि मुझे नई कॉपियों और पुरानी पुस्तकों में से ऐसी गंध आने लगती कि मन बहुत उदास होने लगता था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e0a322d4-d58c-4ac4-acf9-1825e7de94ec', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसका ठीक-ठीक कारण तो कभी समझ में नहीं आया परंतु जितनी भी मनोविज्ञान की जानकारी है, इस अरुचि का कारण यही समझ में आया कि आगे की श्रेणी की कुछ मुश्किल पढ़ाई और नए मास्टरों की मार-पीट का भय ही कहीं भीतर जमकर बैठा था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d5753492-4bb8-440c-85af-7503b72a9397', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पी.टी. साहब अपनी चमकीली आँखें हल्के से झपकाते कहते—'शाबाश! वैल बिगिन अगेन—वन, टू, थ्री, थ्री, टू, वन!' उनकी एक शाबाश ऐसे लगने लगती जैसे हमने किसी फौज के सभी तमगे जीत लिए हों। कभी यही एक शाबाश, सभी मास्टरों की ओर से, हमारी सभी कापियों पर साल भर की लिखी 'गुंओं' (गुड का बहुवचन) से अधिक मूल्यवान लगने लगती। कभी ऐसा भी लगता कि कई साल की सख्त मेहनत से प्राप्त की पढ़ाई से भी पी.टी. साहब के डिसिप्लिन में रहकर प्राप्त की 'गुडविल' बहुत बड़ी थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('2e51d922-45b6-4529-9275-0d792d9d5cbd', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे घर में किसी को भी पढ़ाई में दिलचस्पी न थी। यदि नई किताबें लानी पड़तीं (जो तब एक-दो रुपये में आ जाया करतीं) तो शायद इसी बहाने पढ़ाई तीसरी-चौथी श्रेणी में ही छूट जाती। कोई सात साल स्कूल में रहा तो एक कारण पुरानी किताबें मिल जाना भी था। कॉपियों, पेंसिलों, होल्डर या स्याही-दवात में भी मुश्किल से एक-दो रुपये साल भर में खर्च हुआ करते। परंतु उस जमाने में एक रुपया भी बहुत बड़ी 'रकम' हुआ करती थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('cb29ee81-13f7-40ca-8aa5-e06c87952488', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुछ ऐसी भी भावना थी कि अधिक अध्यापक एक साल में ऐसी अपेक्षा करने लगते कि जैसे हम 'हरफनमौला' हो गए हों। यदि उनकी आशाओं पर पूरे नहीं हो पाते तो कुछ तो जैसे 'चमड़ी उधेड़ देने को तैयार रहते', इन्हीं कुछ कारणों से केवल किताबों-कॉपियों की गंध से ही नहीं, बाहर के बड़े गेट से दस-पंद्रह गज दूर स्कूल के कमरों तक रास्ते के दोनों ओर जो अलियार के झाड़ उगे थे उनकी गंध भी मन उदास कर दिया करती।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('0d3fe43e-7435-4df4-9781-53fd3d13e9c7', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु स्कूल एक-दो कारणों से अच्छा भी लगने लगा था। मास्टर प्रीतमचंद जब हम स्काउटों को परेड करवाते तो लेफ्ट-राइट की आवाज़ या मुँह में ली व्हिसल से मार्च कराया करते। फिर राइट टर्न या लेफ्ट टर्न या अबाउट टर्न कहने पर छोटे-छोटे बूटों की एड़ियों पर दाएँ-बाएँ या एकदम पीछे मुड़कर बूटों की ठक-ठक करते अकड़कर चलते तो लगता जैसे हम विद्यार्थी नहीं, बहुत महत्त्वपूर्ण 'आदमी' हों—फौजी जवान।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f9fcd59b-53d8-4301-9c24-8c6b7db8d5ff', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूसरे विश्व-युद्ध का समय था, परंतु हमारी नाभा रियासत का राजा अंग्रेजों ने 1923 में गिरफ़्तार कर लिया था और तमिलनाडु में कोडाईकनाल में ही, जंग शुरू होने से पहले उसका देहांत हो गया था। उस राजा का बेटा, कहते थे अभी विलायत में पढ़ रहा था। इसलिए हमारे देसी रियासत में भी अंग्रेज की ही चलती थी फिर भी राजा के न रहते, अंग्रेज हमारी रियासत के गाँवों से 'जब रन' भर्ती नहीं कर पाया था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('536b96c8-8e6f-463c-94b4-14af40967b11', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लोगों को फौज में भर्ती करने के लिए जब कुछ अफ़सर आते तो उनके साथ कुछ नौटंकी वाले भी हुआ करते। वे रात को खुले मैदान में शामियाने लगाकर लोगों को फौज के सुख-आराम, बहादुरी के दृश्य दिखाकर आकर्षित किया करते। उनका एक गाना अभी भी याद है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('472370d0-4a54-4107-91a2-7d3e08b614e3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भर्ती हो जा रे रंगरूट भर्ती हो जा रे--- अठे मिले सैं टूटे लीतर उठे मिलैंगे बूट, भर्ती हो जा रे, हो जा रे रंगरूट। अठे पहन सैं फटे पुराने उठे मिलेंगे सूट$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d10733f5-f97f-4a33-bc26-bf8227270060', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुछ ऐसी भी भावना थी कि अधिक अध्यापक एक साल में ऐसी अपेक्षा करने लगते कि जैसे हम 'हरफनमौला' हो गए हों। यदि उनकी आशाओं पर पूरे नहीं हो पाते तो कुछ तो जैसे 'चमड़ी उधेड़ देने को तैयार रहते'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
