  ('0ab05bbb-fc73-4cbf-b520-eb27d3eb155c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारी नाभा रियासत का राजा अंग्रेजों ने 1923 में गिरफ़्तार कर लिया था और तमिलनाडु में कोडाईकनाल में ही, जंग शुरू होने से पहले उसका देहांत हो गया था। उस राजा का बेटा, कहते थे अभी विलायत में पढ़ रहा था। इसलिए हमारे देसी रियासत में भी अंग्रेज की ही चलती थी$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('0164f28e-20a0-4104-b517-f3c310ecb1ef', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लोगों को फौज में भर्ती करने के लिए जब कुछ अफ़सर आते तो उनके साथ कुछ नौटंकी वाले भी हुआ करते। वे रात को खुले मैदान में शामियाने लगाकर लोगों को फौज के सुख-आराम, बहादुरी के दृश्य दिखाकर आकर्षित किया करते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('bd1059c6-0caf-4b53-8aa6-585362cde2ff', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भर्ती हो जा रे रंगरूट भर्ती हो जा रे--- अठे मिले सैं टूटे लीतर उठे मिलैंगे बूट, भर्ती हो जा रे, हो जा रे रंगरूट। अठे पहन सैं फटे पुराने उठे मिलेंगे सूट$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('2375bb7d-0e96-45ac-ae92-5362d1725d37', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भरती हो जा रे, हो जा रे रंगरूट इन्हीं बातों से आकर्षित हो कुछ नौजवान भर्ती के लिए तैयार हो जाया करते। कभी-कभी हमें भी महसूस होता कि हम भी फौजी जवानों से कम नहीं। धोबी की धुली वर्दी और पॉलिश किए बूट और जुराबों को पहने जब हम स्काउटिंग की परेड करते तो लगता हम फौजी ही हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f8ce0ff3-0551-4a1e-ae28-a7069f149e7c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मास्टर प्रीतमचंद को स्कूल के समय में कभी भी हमने मुस्कुराते या हँसते न देखा था। उनका ठिगना कद, दुबला-पतला परंतु गठीला शरीर, माता के दागों से भरा चेहरा और बाज-सी तेज आँखें, खाकी वर्दी, चमड़े के चौड़े पंजों वाले बूट—सभी कुछ ही भयभीत करने वाला हुआ करता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c0cd07a4-1845-4c66-8ace-98ed9894d2d2', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनके बूटों की ऊँची एड़ियों के नीचे भी खुरियाँ लगी रहतीं, जैसे ताँगे के घोड़े के पैरों में लगी रहती हैं। अगले हिस्से में, पंजों के नीचे मोटे सिरों वाले कील ठुके होते। यदि वह सख्त जगह पर भी चलते तो खुरियों और कीलों के निशान वहाँ भी दिखाई देते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3b98aa2f-55c4-449d-938c-b8c6cb130884', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हम ध्यान से देखते, इतने बड़े और भारी-भारी बूट पहनने के बावजूद उनके टखनों में कहीं मोच तक नहीं आती थी। (उनको देखकर हम यदि घरवालों से बूटों की माँग करते तो माँ-बाप यही कहते कि टखने टेढ़े हो जाएँगे, सारी उमर सीधे न चल पाओगे।)$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('feb4daa7-d7d8-417f-869b-7eb4b30f16cd', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मास्टर प्रीतमचंद से हमारा डरना तो स्वाभाविक था, परंतु हम उनसे नफरत भी करते थे। कारण तो उसका मार-पीट था। हम सभी को (जो मेरी उमर के हैं) वह दिन नहीं भूल पाया जिस दिन वह हमें चौथी श्रेणी में फारसी पढ़ाने लगे थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cd3392af-ce59-4292-bb07-de7a172b4e7b', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमें उर्दू का तो तीसरी श्रेणी तक अच्छा अभ्यास हो गया था परंतु फारसी तो अंग्रेजी से भी मुश्किल थी। अभी हमें पढ़ते एक सप्ताह भी न हुआ होगा कि प्रीतमचंद ने हमें एक शब्द-रूप याद करने को कहा और आदेश दिया कि कल इसी घंटी में जुबानी सुनेंगे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('45e07fd4-54d0-4544-8d85-eaebc00b854d', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हम सभी घर लौटकर, रात देर तक उसी शब्द-रूप को बार-बार याद करते रहे परंतु केवल दो-तीन ही लड़के थे जिन्हें आधी या कुछ अधिक शब्द-रूप याद हो पाया। दूसरे दिन बारी-बारी सबको सुनाने के लिए कहा तो एक भी लड़का न सुना पाया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ba8b829b-f6d9-46ff-8722-705640f99f87', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तभी मास्टर जी गुर्राए—सभी कान पकड़ो। हमने झुककर टाँगों के पीछे से बाँहें निकालकर कान पकड़े तो वह गुस्से से चीखे—पीठ ऊँची करो।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4e8a3f0b-3062-40d0-92c7-38e958b3e641', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पीठ ऊँची करके कान पकड़ने से, तीन-चार मिनट में ही टाँगों में जलन होने लगती थी। मेरे जैसे कमजोर तो टाँगों के थकने से कान पकड़े हुए ही गिर पड़ते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('efc78bdb-8065-4f43-a8ee-3dd45f54dbf1', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब तक मेरी और हरबंस की बारी आई तब तक हेडमास्टर शर्मा जी अपने दफ्तर में आ चुके थे। जब हमें सजा दी जा रही थी तो उसके कुछ$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('30de68da-99f9-4337-93e3-6a3ff4dd953e', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुछ दिन पहले शर्मा जी, स्कूल की पूरब की ओर बने सरकारी अस्पताल में डॉक्टर कपलाश से मिलने गए थे। वह दफ्तर के सामने की ओर चले आए। आते ही जो कुछ उन्होंने देखा वह सहन नहीं कर पाए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('c690891e-bf5e-4079-9db4-e18b4060e844', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$शायद यह पहला अवसर था कि वह पी.टी. प्रीतमचंद की उस बर्बरता को सहन न कर पाए। बहुत उत्तेजित हो गए थे।—'व्हाट आर यू डूइंग, इज इट दा वे टू पनिश दा स्टूडेंट्स ऑफ फोर्थ क्लास? स्टॉप इट एट वन्स!'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('0ae2fa5f-c94e-4088-800e-ca8bf45cfec6', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमें तब अंग्रेजी नहीं आती थी, क्योंकि उस समय पाँचवीं श्रेणी से अंग्रेजी पढ़ानी शुरू की जाती थी। परंतु हमारे स्कूल के सातवीं-आठवीं श्रेणी के लड़कों ने बताया था कि शर्मा जी ने कहा था—क्या करते हैं? क्या चौथी श्रेणी को सजा देने का यह ढंग है? इसे फौरन बंद करो।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('bd63955c-19bf-41e4-bd6a-3ebbac569f45', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$शर्मा जी गुस्से से काँपते बरामदे से ही अपने दफ्तर में चले गए थे। फिर जब प्रीतमचंद कई दिन स्कूल नहीं आए तो यह बात सभी मास्टरों की जुबान पर थी कि हेडमास्टर शर्मा जी ने उन्हें मुअत्तल करके अपनी ओर से आदेश लिखकर, मंजूरी के लिए हमारी रियासत की राजधानी, नाभा भेज दिया है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('24dd885d-cce8-49ff-b90c-8c8b9235c892', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वहाँ हरझीललाल नाम के 'महकमा-ए-तालीम' के डायरेक्टर थे जिनसे ऐसे आदेश की मंजूरी आवश्यक थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('3cf1c257-66e3-46df-8cc4-292ca53ec0f7', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$शर्मा जी, स्कूल की पूरब की ओर बने सरकारी अस्पताल में डॉक्टर कपलाश से मिलने गए थे। वह दफ्तर के सामने की ओर चले आए। आते ही जो कुछ उन्होंने देखा वह सहन नहीं कर पाए। शायद यह पहला अवसर था कि वह पी.टी. प्रीतमचंद की उस बर्बरता को सहन न कर पाए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8069bd78-03e9-4677-9459-53dcb8030188', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बहुत उत्तेजित हो गए थे।—'व्हाट आर यू डूइंग, इज इट दा वे टू पनिश दा स्टूडेंट्स ऑफ फोर्थ क्लास? स्टॉप इट एट वन्स!' हमें तब अंग्रेजी नहीं आती थी, क्योंकि उस समय पाँचवीं श्रेणी से अंग्रेजी पढ़ानी शुरू की जाती थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8ffa734f-8899-4a64-887e-a810f9453da2', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु हमारे स्कूल के सातवीं-आठवीं श्रेणी के लड़कों ने बताया था कि शर्मा जी ने कहा था—क्या करते हैं? क्या चौथी श्रेणी को सजा देने का यह ढंग है? इसे फौरन बंद करो। शर्मा जी गुस्से से काँपते बरामदे से ही अपने दफ्तर में चले गए थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('fb399ebe-85c1-4aaa-b9b7-b77f84749693', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फिर जब प्रीतमचंद कई दिन स्कूल नहीं आए तो यह बात सभी मास्टरों की जुबान पर थी कि हेडमास्टर शर्मा जी ने उन्हें मुअत्तल करके अपनी ओर से आदेश लिखकर, मंजूरी के लिए हमारी रियासत की राजधानी, नाभा भेज दिया है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d955cdc1-d818-47e2-9c77-864515ad70dd', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वहाँ हरझीललाल नाम के 'महकमा-ए-तालीम' के डायरेक्टर थे जिनसे ऐसे आदेश की मंजूरी आवश्यक थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d12f8244-42e7-4511-a9f2-0c3f71d244ce', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे साथ खेलने वाले सभी बच्चों का हाल एक-सा होता। नंगे पाँव, फटी-मैली सी कच्छी और टूटे बटनों वाले कई जगह से फटे कुर्ते और बिखरे बाल। जब लकड़ी के ढेर पर चढ़कर खेलते नीचे को भागते तो गिरकर कई तो जाने कहाँ-कहाँ चोट खा लेते और पहले ही फटे-पुराने कुर्ते तार-तार हो जाते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('9bdfc362-6fae-4ee2-9d9a-662da34295c6', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$धूल भरे, कई जगह से छिपे पाँव, पिंडलियाँ या लहू के ऊपर जमी रेत-मिट्टी से लथपथ घुटने लेकर जाते तो सभी की माँ-बहनें उन पर तरस खाने की जगह और पिटाई करतीं। कईयों के बाप बड़े गुस्सैल थे। पीटने लगते तो यह ध्यान भी न रखते कि छोटे बच्चे के नाक-मुँह से लहू बहने लगा है या उसके कहाँ चोट लगी है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('83ed2287-6226-4b8a-a0e9-6b2ee5453e5c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु इतनी बुरी पिटाई होने पर भी दूसरे दिन फिर खेलने चले आते। (यह बात तब ठीक से समझ आई जब स्कूल अध्यापक बनने के लिए एक ट्रेनिंग करने गया और वहाँ बाल-मनोविज्ञान का विषय पढ़ा। ऐसी बातों के बारे में तभी जान पाया कि बच्चों को खेलना क्यों इतना अच्छा लगता है कि बुरी तरह पिटाई होने पर भी फिर खेलने चले आते हैं।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('609ca493-1bf6-478b-b9df-620d72299753', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे साथ खेलने वाले अधिकतर साथी हमारे जैसे ही परिवारों के हुआ करते। सारे मुहल्ले में बहुत परिवार तो, हमारी तरह आसपास के गाँवों से ही आकर बसे थे। दो-तीन घर, साथ की उजड़ी-सी गली में रहने वाले लोगों के थे। हमारी सभी की आदतें भी कुछ मिलती-जुलती थीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('f16c6184-e9db-4871-87f1-b350e962f10a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनमें से अधिक तो स्कूल जाते ही न थे, जो कभी गए भी, पढ़ाई में रुचि न होने के कारण किसी दिन बस्ता तालाब में फेंक आए और फिर स्कूल गए ही नहीं, न ही माँ-बाप ने ज़बरदस्ती भेजा। यहाँ तक कि पर्चूनिए, आढ़तिए भी अपने बच्चों को स्कूल भेजना ज़रूरी न समझते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('704a1abd-37c2-4ead-9604-0a77c02dd78b', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कभी किसी स्कूल अध्यापक से बात होती तो कहते—मास्टर जी हमने इसे क्या तहसीलदार लगवाना है। थोड़ा बड़ा हो जाए तो पंडित घनश्याम दास से लंडे पढ़वाकर दुकान पर बहियाँ लिखने लगा लेंगे। पंडित छह-आठ महीने में लंडे और मुनीमी का सभी काम सिखा देगा। वहाँ तो अभी तक अलिफ़-बे जीम-चे भी सीख नहीं पाया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('3373f335-86b9-46e8-943e-665fd262ae18', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे साथ खेलने वाले सभी बच्चों का हाल एक-सा होता। नंगे पाँव, फटी-मैली सी कच्छी और टूटे बटनों वाले कई जगह से फटे कुर्ते और बिखरे बाल। जब लकड़ी के ढेर पर चढ़कर खेलते नीचे को भागते तो गिरकर कई तो जाने कहाँ-कहाँ चोट खा लेते और पहले ही फटे-पुराने कुर्ते तार-तार हो जाते। धूल भरे, कई जगह से छिपे पाँव, पिंडलियाँ या लहू के ऊपर जमी रेत-मिट्टी से लथपथ घुटने लेकर जाते तो सभी की माँ-बहनें उन पर तरस खाने की जगह और पिटाई करतीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('64b7d79e-e3dc-4d4d-959e-f637d122b0c5', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कईयों के बाप बड़े गुस्सैल थे। पीटने लगते तो यह ध्यान भी न रखते कि छोटे बच्चे के नाक-मुँह से लहू बहने लगा है या उसके कहाँ चोट लगी है। परंतु इतनी बुरी पिटाई होने पर भी दूसरे दिन फिर खेलने चले आते। (यह बात तब ठीक से समझ आई जब स्कूल अध्यापक बनने के लिए एक ट्रेनिंग करने गया और वहाँ बाल-मनोविज्ञान का विषय पढ़ा।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('d516c01c-f227-49da-b9ab-4988a98b3a2b', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे साथ खेलने वाले अधिकतर साथी हमारे जैसे ही परिवारों के हुआ करते। सारे मुहल्ले में बहुत परिवार तो, हमारी तरह आसपास के गाँवों से ही आकर बसे थे। दो-तीन घर, साथ की उजड़ी-सी गली में रहने वाले लोगों के थे। हमारी सभी की आदतें भी कुछ मिलती-जुलती थीं। उनमें से अधिक तो स्कूल जाते ही न थे, जो कभी गए भी, पढ़ाई में रुचि न होने के कारण किसी दिन बस्ता तालाब में फेंक आए और फिर स्कूल गए ही नहीं, न ही माँ-बाप ने ज़बरदस्ती भेजा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('ee814e7b-a16e-46ff-8aef-0bc4ffb3a940', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यहाँ तक कि पर्चूनिए, आढ़तिए भी अपने बच्चों को स्कूल भेजना ज़रूरी न समझते। कभी किसी स्कूल अध्यापक से बात होती तो कहते—मास्टर जी हमने इसे क्या तहसीलदार लगवाना है। थोड़ा बड़ा हो जाए तो पंडित घनश्याम दास से लंडे पढ़वाकर दुकान पर बहियाँ लिखने लगा लेंगे। पंडित छह-आठ महीने में लंडे और मुनीमी का सभी काम सिखा देगा। वहाँ तो अभी तक अलिफ़-बे जीम-चे भी सीख नहीं पाया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('081b5984-9c8b-435b-a5f8-e783170bf17c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे आधे से अधिक साथी राजस्थान या हरियाणा से आकर मंडी में व्यापार या दुकानदारो करते आए परिवारों से थे। जब बहुत छोटे थे तो उनकी बोली कम समझ पाते। उनके कुछ शब्द सुनकर हमें हँसी आने लगती। परंतु खेलते तो सभी एक-दूसरे की बात खूब अच्छी तरह समझ लेते। पता भी नहीं चला कि लोकोक्ति अनुसार 'एह खेड़ण दे दिन चार' कैसे, कब बीत गए। (हममें से कोई भी ऐसा न था जो स्कूल के कमरे में बैठकर पढ़ने को 'कैद' न समझता हो।) कुछ अपने माँ-बाप के साथ जैसा भी था, काम कराने लगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('4bdbd6b8-a120-45d5-a276-8e970ec6a4ce', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बचपन में घास अधिक हरी और फूलों की सुगंध अधिक मनमोहक लगती है। यह शब्द शायद आधी सदी पहले किसी पुस्तक में पढ़े थे, परंतु आज तक याद हैं। याद रहने का कारण यही है कि यह वाक्य बचपन की भावनाओं, सोच-समझ के अनुकूल होगा। परंतु स्कूल के अंदर जाने से रास्ते के दोनों ओर जो अलियार के बड़े ढंग से कटे-छंटे झाड़ उगे थे (जिन्हें हम मंडियाँ कहा करते) उनके नीम के पत्तों जैसे पत्तों की महक आज तक भी आँख मूँदकर महसूस कर सकता हूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('ad8e82e5-dc5d-4fdd-89a5-30434e00c6a1', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन दिनों स्कूल की छोटी क्यारियों में फूल भी कई तरह के उगाए जाते थे जिनमें गुलाब, गेंदा और मोतिया की दूध-सी सफेद कलियाँ भी हुआ करतीं। ये कलियाँ इतनी सुंदर और खुशबूदार होती थीं कि हम चंदू चपरासी से आँख बचाकर कभी-कभार एक-दो तोड़ लिया करते। उनकी बहुत तेज़ सुगंध आज भी महसूस कर पाता हूँ, परंतु यह याद नहीं कि उन्हें तोड़कर, कुछ देर सूँघकर फिर क्या किया करते। (शायद जेब में डाल लेते, माँ उसे धोने के समय निकालकर बाहर फेंक देती या हम ही, स्कूल से बाहर आते उन्हें बकरी के मेमनों की भाँति 'चर' जाया करते)।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('84c52cd8-67ca-4af3-91df-f95842721822', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब अगली श्रेणी में दाख़िल होते तो एक ओर तो कुछ बड़े, सयाने होने के एहसास से उत्साहित भी होते, परंतु दूसरी ओर नई, पुरानी कॉपियों-किताबों से जाने कैसी बास आती कि उन्हीं मास्टरों के डर से काँपने लगते जो पिछली श्रेणी में पढ़ा चुके होते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('ba0f6eb1-c202-4d6d-95ad-a4485a534cc6', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तब स्कूल में, शुरू साल में एक-डेढ़ महीना पढ़ाई हुआ करती, फिर डेढ़-दो महीने की छुट्टियाँ शुरू हो जाया करतीं। अब तक जो बात अच्छी तरह याद है वह छुट्टियों के पहले और आखिरी दिनों का फ़र्क था। पहले दो-तीन सप्ताह तो खूब खेल-कूद हुआ करती। हर साल ही माँ के साथ नानीहाल चले जाते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('2b591e79-aec8-46a0-8e81-1bcbeebf5524', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वहाँ नानी खूब दूध-दही, मक्खन खिलाती, बहुत प्यार करती। छोटा सा पिछड़ा गाँव था परंतु तालाब हमारी मंडी के तालाब जितना ही बड़ा था। दोपहर तक तो उस तालाब में नहाते फिर नानी से जो जी में आता माँगकर खाने लगते। नानी हमारे बोलने के ढंग या कम खाने के कारण बहुत खुश होती। अपने पोतों को हमारी तरह बोलने और खाने-पीने को कहती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('270733f8-d2c7-45ef-902d-094e76dde3ee', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जिस साल नानीहाल न जा पाते, उस साल भी अपने घर से थोड़ा बाहर तालाब पर चले जाते। कपड़े उतार पानी में कूद जाते और कुछ समय बाद, भागते हुए एक रेतीले टीले पर जाकर, रेत के ऊपर लेटने लगते। गीले शरीर।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('354d32b3-4f87-4d75-be1c-f4f0de2d1c1a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे आधे से अधिक साथी राजस्थान या हरियाणा से आकर मंडी में व्यापार या दुकानदारो करते आए परिवारों से थे। जब बहुत छोटे थे तो उनकी बोली कम समझ पाते। उनके कुछ शब्द सुनकर हमें हँसी आने लगती। परंतु खेलते तो सभी एक-दूसरे की बात खूब अच्छी तरह समझ लेते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('9f67e7e0-5511-46e8-8a4e-3aa8896a8950', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बचपन में घास अधिक हरी और फूलों की सुगंध अधिक मनमोहक लगती है। यह शब्द शायद आधी सदी पहले किसी पुस्तक में पढ़े थे, परंतु आज तक याद हैं। याद रहने का कारण यही है कि यह वाक्य बचपन की भावनाओं, सोच-समझ के अनुकूल होगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('023c1e3c-9f72-40d9-9b2b-02c7347d1c1a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु स्कूल के अंदर जाने से रास्ते के दोनों ओर जो अलियार के बड़े ढंग से कटे-छंटे झाड़ उगे थे (जिन्हें हम मंडियाँ कहा करते) उनके नीम के पत्तों जैसे पत्तों की महक आज तक भी आँख मूँदकर महसूस कर सकता हूँ। उन दिनों स्कूल की छोटी क्यारियों में फूल भी कई तरह के उगाए जाते थे जिनमें गुलाब, गेंदा और मोतिया की दूध-सी सफेद कलियाँ भी हुआ करतीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('d9136513-cc01-4109-8708-2171debc583d', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारा स्कूल बहुत छोटा था—केवल छोटे-छोटे नौ कमरे थे जो अंग्रेजी के अक्षर एच (H) की भांति बने थे। दाईं ओर पहला कमरा हेडमास्टर श्री मदनमोहन शर्मा जी का था जिसके दरवाजे के आगे हमेशा चिक लटकी रहती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f8158441-5906-4e0f-8074-fae622d78acc', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$स्कूल की प्रेयर (प्रार्थना) के समय वह बाहर आते और सीधी कतारों में कद के अनुसार खड़े लड़कों को देख उनका गोरा चेहरा खिल उठता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0192444e-5776-4242-84c7-4fbc7ad4975d', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सारे अध्यापक, लड़कों की तरह ही कतार बांधकर उनके पीछे खड़े होते। केवल मास्टर प्रीतम चंद 'पीटी' लड़कों की कतारों के पीछे खड़े-खड़े यह देखते थे कि कौन सा लड़का कतार में ठीक नहीं खड़ा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1496a25a-f6f7-4dbd-9ae6-85f878dc883e', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनकी घुड़की तथा ठुंसों के भय से हम सभी कतार के पहले और आखिरी लड़के का ध्यान रखते, सीधे कतार में बने रहने का प्रयत्न करते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('aa26061e-0eae-46a8-9480-fb9bc8b7d803', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सीधी कतार के साथ-साथ हमें यह ध्यान भी रखना होता था कि आगे पीछे खड़े लड़कों के बीच की दूरी भी एक सी हो।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('19e671dc-3803-42c5-8a09-fa3cff74a851', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सभी लड़के उस 'पीटी' से बहुत डरते थे क्योंकि उन जितना सख्त अध्यापक न कभी किसी ने देखा, न सुना था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5f80dc40-4fba-42a1-b055-8ffff9b17b98', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यदि कोई लड़का अपना सिर भी इधर-उधर हिला लेता या पांव से दूसरी पिंडली खुजलाने लगता तो वह उसकी ओर बाघ की तरह झपट पड़ते और 'खाल खींचने' के मुहावरे को प्रत्यक्ष करके दिखा देते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9a6aea84-f62d-44da-9c17-97ba1fda3df2', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारा स्कूल बहुत छोटा था—केवल छोटे-छोटे नौ कमरे थे जो अंग्रेजी के अक्षर एच (H) की भांति बने थे। दाईं ओर पहला कमरा हेडमास्टर श्री मदनमोहन शर्मा जी का था जिसके दरवाजे के आगे हमेशा चिक लटकी रहती। स्कूल की प्रेयर (प्रार्थना) के समय वह बाहर आते और सीधी कतारों में कद के अनुसार खड़े लड़कों को देख उनका गोरा चेहरा खिल उठता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1f561ed0-a0e8-4b6a-81cc-b4e03ed429ce', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सारे अध्यापक, लड़कों की तरह ही कतार बांधकर उनके पीछे खड़े होते। केवल मास्टर प्रीतम चंद 'पीटी' लड़कों की कतारों के पीछे खड़े-खड़े यह देखते थे कि कौन सा लड़का कतार में ठीक नहीं खड़ा। उनकी घुड़की तथा ठुंसों के भय से हम सभी कतार के पहले और आखिरी लड़के का ध्यान रखते, सीधे कतार में बने रहने का प्रयत्न करते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e1d7bed7-9349-4b88-bc36-0f8b44a76e68', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सभी लड़के उस 'पीटी' से बहुत डरते थे क्योंकि उन जितना सख्त अध्यापक न कभी किसी ने देखा, न सुना था। यदि कोई लड़का अपना सिर भी इधर-उधर हिला लेता या पांव से दूसरी पिंडली खुजलाने लगता तो वह उसकी ओर बाघ की तरह झपट पड़ते और 'खाल खींचने' के मुहावरे को प्रत्यक्ष करके दिखा देते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d1027ed4-21eb-43a9-96dc-66874b13df29', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु हेडमास्टर शर्मा जी उसके बिल्कुल उलट स्वभाव के थे। वह पाँचवीं और आठवीं श्रेणी को अंग्रेजी स्वयं पढ़ाया करते थे। हमारे में से किसी को भी याद न था कि पाँचवीं श्रेणी में कभी भी उन्हें, किसी गलती के कारण किसी की 'चमड़ी उधेड़ते' देखा या सुना हो। (चमड़ी उधेड़ना हमारे लिए बिल्कुल ऐसा शब्द था जैसे हमारे 'सरकारी मिडिल स्कूल' का नाम।) अधिक से अधिक वह गुस्से में बहुत जल्दी-जल्दी आँखें झपकते, अपने लंबे हाथ की उल्टी उँगलियों से एक 'चपत' हमारी गाल पर मार देते तो मेरे जैसे सबसे कमज़ोर शरीर वाले भी सिर झुकाकर मुँह नीचा किए हँस देते। वह चपत तो जैसे हमें भाई भीखे की नमकीन पापड़ी जैसी मज़ेदार लगती जो तब पैसे की शायद दो आ जाया करतीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('34930881-adec-463d-808c-dd9108a129ba', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु तब भी स्कूल हमारे लिए ऐसी जगह न थी जहाँ खुशी से भागे जाएँ। पहली कच्ची श्रेणी से लेकर चौथी श्रेणी तक, केवल पाँच-सात लड़कों को छोड़ हम सभी रोते चिल्लाते ही स्कूल जाया करते। परंतु कभी-कभी ऐसी सभी स्थितियों के रहते स्कूल अच्छा भी लगने लगता। जब स्काउटिंग का अभ्यास करवाते समय पीटी साहब नीली-पीली झंडियाँ हाथों में पकड़ाकर वन टू थ्री कहते, झंडियाँ ऊपर-नीचे, दाएँ-बाएँ करवाते तो हवा में लहराती और...$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('645b0e22-98b9-40e7-b3fb-36371a632746', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु हेडमास्टर शर्मा जी उसके बिल्कुल उलट स्वभाव के थे। वह पाँचवीं और आठवीं श्रेणी को अंग्रेजी स्वयं पढ़ाया करते थे। हमारे में से किसी को भी याद न था कि पाँचवीं श्रेणी में कभी भी उन्हें, किसी गलती के कारण किसी की 'चमड़ी उधेड़ते' देखा या सुना हो। (चमड़ी उधेड़ना हमारे लिए बिल्कुल ऐसा शब्द था जैसे हमारे 'सरकारी मिडिल स्कूल' का नाम।) अधिक से अधिक वह गुस्से में बहुत जल्दी-जल्दी आँखें झपकते, अपने लंबे हाथ की उल्टी उँगलियों से एक 'चपत' हमारी गाल पर मार देते तो मेरे जैसे सबसे कमज़ोर शरीर वाले भी सिर झुकाकर मुँह नीचा किए हँस देते। वह चपत तो जैसे हमें भाई भीखे की नमकीन पापड़ी जैसी मज़ेदार लगती जो तब पैसे की शायद दो आ जाया करतीं। परंतु तब भी स्कूल हमारे लिए ऐसी जगह न थी जहाँ खुशी से भागे जाएँ। पहली कच्ची श्रेणी से लेकर चौथी श्रेणी तक, केवल पाँच-सात लड़कों को छोड़ हम सभी रोते चिल्लाते ही स्कूल जाया करते। परंतु कभी-कभी ऐसी सभी स्थितियों के रहते स्कूल अच्छा भी लगने लगता। जब स्काउटिंग का अभ्यास करवाते समय पीटी साहब नीली-पीली झंडियाँ हाथों में पकड़ाकर वन टू थ्री कहते, झंडियाँ ऊपर-नीचे, दाएँ-बाएँ करवाते तो हवा में लहराती और...$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('123d7e2b-29a8-4476-bd70-4f55accb1f40', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु हेडमास्टर शर्मा जी उसके बिल्कुल उलट स्वभाव के थे। वह पाँचवीं और आठवीं श्रेणी को अंग्रेजी स्वयं पढ़ाया करते थे। हमारे में से किसी को भी याद न था कि पाँचवीं श्रेणी में कभी भी उन्हें, किसी गलती के कारण किसी की 'चमड़ी उधेड़ते' देखा या सुना हो।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('072d2cd2-e0a1-4969-afa8-d75d2386ed43', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अधिक से अधिक वह गुस्से में बहुत जल्दी-जल्दी आँखें झपकते, अपने लंबे हाथ की उल्टी उँगलियों से एक 'चपत' हमारी गाल पर मार देते तो मेरे जैसे सबसे कमज़ोर शरीर वाले भी सिर झुकाकर मुँह नीचा किए हँस देते। वह चपत तो जैसे हमें भाई भीखे की नमकीन पापड़ी जैसी मज़ेदार लगती जो तब पैसे की शायद दो आ जाया करतीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5a63c3e6-dd93-4c18-b2f8-6be2c75e6729', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु तब भी स्कूल हमारे लिए ऐसी जगह न थी जहाँ खुशी से भागे जाएँ। पहली कच्ची श्रेणी से लेकर चौथी श्रेणी तक, केवल पाँच-सात लड़कों को छोड़ हम सभी रोते चिल्लाते ही स्कूल जाया करते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
