  ('7006e016-223f-403d-8587-c12f298e3c3c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हेडमास्टर शर्मा जी उसके बिल्कुल उलट स्वभाव के थे। वह पाँचवीं और आठवीं श्रेणी को अंग्रेजी स्वयं पढ़ाया करते थे। हमारे में से किसी को भी याद न था कि पाँचवीं श्रेणी में कभी भी उन्हें, किसी गलती के कारण किसी की 'चमड़ी उधेड़ते' देखा या सुना हो। (चमड़ी उधेड़ना हमारे लिए बिल्कुल ऐसा शब्द था जैसे हमारे 'सरकारी मिडिल स्कूल' का नाम।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f0df91b7-2ad8-421b-be2a-fd85e571fd90', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अधिक से अधिक वह गुस्से में बहुत जल्दी-जल्दी आँखें झपकते, अपने लंबे हाथ की उल्टी उँगलियों से एक 'चपत' हमारी गाल पर मार देते तो मेरे जैसे सबसे कमज़ोर शरीर वाले भी सिर झुकाकर मुँह नीचा किए हँस देते। वह चपत तो जैसे हमें भाई भीखे की नमकीन पापड़ी जैसी मज़ेदार लगती जो तब पैसे की शायद दो आ जाया करतीं। परंतु तब भी स्कूल हमारे लिए ऐसी जगह न थी जहाँ खुशी से भागे जाएँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b36f6e9e-2884-4da0-b857-b92123739583', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पहली कच्ची श्रेणी से लेकर चौथी श्रेणी तक, केवल पाँच-सात लड़कों को छोड़ हम सभी रोते चिल्लाते ही स्कूल जाया करते। परंतु कभी-कभी ऐसी सभी स्थितियों के रहते स्कूल अच्छा भी लगने लगता। जब स्काउटिंग का अभ्यास करवाते समय पीटी साहब नीली-पीली झंडियाँ हाथों में पकड़ाकर वन टू थ्री कहते, झंडियाँ ऊपर-नीचे, दाएँ-बाएँ करवाते तो हवा में लहराती और...$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5b3a295f-e507-4001-98c9-cce7959e9cf8', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पी.टी. साहब अपनी चमकीली आँखें हल्के से झपकाते कहते—'शाबाश! वैल बिगिन अगेन—वन, टू, थ्री, थ्री, टू, वन!' उनकी एक शाबाश ऐसे लगने लगती जैसे हमने किसी फौज के सभी तमगे जीत लिए हों। कभी यही एक शाबाश, सभी मास्टरों की ओर से, हमारी सभी कापियों पर साल भर की लिखी 'गुंओं' (गुड का बहुवचन) से अधिक मूल्यवान लगने लगती। कभी ऐसा भी लगता कि कई साल की सख्त मेहनत से प्राप्त की पढ़ाई से भी पी.टी. साहब के डिसिप्लिन में रहकर प्राप्त की 'गुडविल' बहुत बड़ी थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('35002e0a-f59d-4ca6-88d2-2cbdeae4c3ea', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु यह भी एहसास रहता कि जैसे गुरुद्वारे का भाई जी कथा करते समय बताया करता कि सतगुरु के भय से ही प्रेम जागता है, ऐसे ही पी.टी. साहब के प्रति हमारी प्रेम की भावना जग जाती। (यह ऐसा भी है कि आपको रोष फटकारने वाला कोई 'अपना' यदि साल भर के बाद एक बार 'शाबाश' कह दे तो यह चमत्कार-सा लगने लगता है—हमारी दशा भी कुछ ऐसी हुआ करती।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('2ba02745-f466-4703-8661-406d273d58d1', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हर वर्ष अगली श्रेणी में प्रवेश करते समय मुझे पुरानी पुस्तकें मिला करतीं। हमारे हेडमास्टर शर्मा जी एक लड़के को उसके घर जाकर पढ़ाया करते थे। वे धनाढ्य लोग थे। उनका लड़का मुझसे एक-दो साल बड़ा होने के कारण मेरे से एक श्रेणी आगे रहा। हर साल अप्रैल में जब पढ़ाई का नया साल आरंभ होता तो शर्मा जी उसकी एक साल पुरानी पुस्तकें ले आते। हमारे घर में किसी को भी पढ़ाई में दिलचस्पी न थी। यदि नई किताबें लानी पड़तीं (जो तब एक-दो रुपये में आ जाया करतीं) तो शायद इसी बहाने पढ़ाई तीसरी-चौथी श्रेणी में ही छूट जाती। कोई सात साल स्कूल में रहा तो एक कारण पुरानी किताबें मिल जाना भी था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a5b97281-2217-4665-8752-6db655d1df7a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कॉपियों, पेंसिलों, होल्डर या स्याही-दवात में भी मुश्किल से एक-दो रुपये साल भर में खर्च हुआ करते। परंतु उस जमाने में एक रुपया भी बहुत बड़ी 'रकम' हुआ करती थी। एक रुपये में एक सेर घी आया करता और दो रुपये की एक मन (चालीस सेर) गंदम। इसी कारण, खाते-पीते घरों के लड़के ही स्कूल जाया करते। हमारे दो परिवारों में मैं पहला लड़का था जो स्कूल जाने लगा था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ad794708-0e39-4929-bbbc-d5726da0c3a3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु किसी भी नई श्रेणी में जाने का ऐसा चाव कभी भी महसूस नहीं हुआ जिसका जिक्र कुछ लड़के किया करते। अजीब बात थी कि मुझे नई कॉपियों और पुरानी पुस्तकों में से ऐसी गंध आने लगती कि मन बहुत उदास होने लगता था। इसका ठीक-ठीक कारण तो कभी समझ में नहीं आया परंतु जितनी भी मनोविज्ञान की जानकारी है, इस अरुचि का कारण यही समझ में आया कि आगे की श्रेणी की कुछ मुश्किल पढ़ाई और नए मास्टरों की मार-पीट का भय ही कहीं भीतर जमकर बैठा था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('9771c15f-5ae3-4949-80c1-d3226f3ccf73', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पी.टी. साहब अपनी चमकीली आँखें हल्के से झपकाते कहते—'शाबाश! वैल बिगिन अगेन—वन, टू, थ्री, थ्री, टू, वन!' उनकी एक शाबाश ऐसे लगने लगती जैसे हमने किसी फौज के सभी तमगे जीत लिए हों। कभी यही एक शाबाश, सभी मास्टरों की ओर से, हमारी सभी कापियों पर साल भर की लिखी 'गुंओं' (गुड का बहुवचन) से अधिक मूल्यवान लगने लगती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('c9433cea-3a37-45af-96df-985539f5dbf3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कभी ऐसा भी लगता कि कई साल की सख्त मेहनत से प्राप्त की पढ़ाई से भी पी.टी. साहब के डिसिप्लिन में रहकर प्राप्त की 'गुडविल' बहुत बड़ी थी। परंतु यह भी एहसास रहता कि जैसे गुरुद्वारे का भाई जी कथा करते समय बताया करता कि सतगुरु के भय से ही प्रेम जागता है, ऐसे ही पी.टी. साहब के प्रति हमारी प्रेम की भावना जग जाती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f955cf8c-6850-41fb-97d7-d26ca56192c4', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे हेडमास्टर शर्मा जी एक लड़के को उसके घर जाकर पढ़ाया करते थे। वे धनाढ्य लोग थे। उनका लड़का मुझसे एक-दो साल बड़ा होने के कारण मेरे से एक श्रेणी आगे रहा। हर साल अप्रैल में जब पढ़ाई का नया साल आरंभ होता तो शर्मा जी उसकी एक साल पुरानी पुस्तकें ले आते। हमारे घर में किसी को भी पढ़ाई में दिलचस्पी न थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('84fd50fb-58bf-4a31-90e8-eaf1757d6f22', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यदि नई किताबें लानी पड़तीं (जो तब एक-दो रुपये में आ जाया करतीं) तो शायद इसी बहाने पढ़ाई तीसरी-चौथी श्रेणी में ही छूट जाती। कोई सात साल स्कूल में रहा तो एक कारण पुरानी किताबें मिल जाना भी था। कॉपियों, पेंसिलों, होल्डर या स्याही-दवात में भी मुश्किल से एक-दो रुपये साल भर में खर्च हुआ करते। परंतु उस जमाने में एक रुपया भी बहुत बड़ी 'रकम' हुआ करती थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8ecc5999-d4ed-4fac-8def-ce5d346c83e1', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक रुपये में एक सेर घी आया करता और दो रुपये की एक मन (चालीस सेर) गंदम। इसी कारण, खाते-पीते घरों के लड़के ही स्कूल जाया करते। हमारे दो परिवारों में मैं पहला लड़का था जो स्कूल जाने लगा था। परंतु किसी भी नई श्रेणी में जाने का ऐसा चाव कभी भी महसूस नहीं हुआ जिसका जिक्र कुछ लड़के किया करते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('c4d8f9b8-745b-490e-9c76-67af5ff09987', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुछ ऐसी भी भावना थी कि अधिक अध्यापक एक साल में ऐसी अपेक्षा करने लगते कि जैसे हम 'हरफनमौला' हो गए हों। यदि उनकी आशाओं पर पूरे नहीं हो पाते तो कुछ तो जैसे 'चमड़ी उधेड़ देने को तैयार रहते', इन्हीं कुछ कारणों से केवल किताबों-कॉपियों की गंध से ही नहीं, बाहर के बड़े गेट से दस-पंद्रह गज दूर स्कूल के कमरों तक रास्ते के दोनों ओर जो अलियार के झाड़ उगे थे उनकी गंध भी मन उदास कर दिया करती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('cd4b3d94-9af3-4c53-baf9-7a421673a724', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु स्कूल एक-दो कारणों से अच्छा भी लगने लगा था। मास्टर प्रीतमचंद जब हम स्काउटों को परेड करवाते तो लेफ्ट-राइट की आवाज़ या मुँह में ली व्हिसल से मार्च कराया करते। फिर राइट टर्न या लेफ्ट टर्न या अबाउट टर्न कहने पर छोटे-छोटे बूटों की एड़ियों पर दाएँ-बाएँ या एकदम पीछे मुड़कर बूटों की ठक-ठक करते अकड़कर चलते तो लगता जैसे हम विद्यार्थी नहीं, बहुत महत्त्वपूर्ण 'आदमी' हों—फौजी जवान।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('5363605e-aef1-4ded-8f8c-858904b458ab', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूसरे विश्व-युद्ध का समय था, परंतु हमारी नाभा रियासत का राजा अंग्रेजों ने 1923 में गिरफ़्तार कर लिया था और तमिलनाडु में कोडाईकनाल में ही, जंग शुरू होने से पहले उसका देहांत हो गया था। उस राजा का बेटा, कहते थे अभी विलायत में पढ़ रहा था। इसलिए हमारे देसी रियासत में भी अंग्रेज की ही चलती थी फिर भी राजा के न रहते, अंग्रेज हमारी रियासत के गाँवों से 'जब रन' भर्ती नहीं कर पाया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8a63fa85-7da1-49e4-954d-3ea2fed5a526', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लोगों को फौज में भर्ती करने के लिए जब कुछ अफ़सर आते तो उनके साथ कुछ नौटंकी वाले भी हुआ करते। वे रात को खुले मैदान में शामियाने लगाकर लोगों को फौज के सुख-आराम, बहादुरी के दृश्य दिखाकर आकर्षित किया करते। उनका एक गाना अभी भी याद है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('6f76a6b5-0df1-4278-848f-dd0580fe07fe', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भर्ती हो जा रे रंगरूट भर्ती हो जा रे--- अठे मिले सैं टूटे लीतर उठे मिलैंगे बूट, भर्ती हो जा रे, हो जा रे रंगरूट। अठे पहन सैं फटे पुराने उठे मिलेंगे सूट$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('bb6c30cf-95e8-41d8-92bd-69752a4ac11e', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुछ ऐसी भी भावना थी कि अधिक अध्यापक एक साल में ऐसी अपेक्षा करने लगते कि जैसे हम 'हरफनमौला' हो गए हों। यदि उनकी आशाओं पर पूरे नहीं हो पाते तो कुछ तो जैसे 'चमड़ी उधेड़ देने को तैयार रहते', इन्हीं कुछ कारणों से केवल किताबों-कॉपियों की गंध से ही नहीं, बाहर के बड़े गेट से दस-पंद्रह गज दूर स्कूल के कमरों तक रास्ते के दोनों ओर जो अलियार के झाड़ उगे थे उनकी गंध भी मन उदास कर दिया करती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('4503834f-b971-4c90-b373-a48b8323aa06', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परंतु स्कूल एक-दो कारणों से अच्छा भी लगने लगा था। मास्टर प्रीतमचंद जब हम स्काउटों को परेड करवाते तो लेफ्ट-राइट की आवाज़ या मुँह में ली व्हिसल से मार्च कराया करते। फिर राइट टर्न या लेफ्ट टर्न या अबाउट टर्न कहने पर छोटे-छोटे बूटों की एड़ियों पर दाएँ-बाएँ या एकदम पीछे मुड़कर बूटों की ठक-ठक करते अकड़कर चलते तो लगता जैसे हम विद्यार्थी नहीं, बहुत महत्त्वपूर्ण 'आदमी' हों—फौजी जवान।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e5cee039-9d1e-4029-8823-893e50b8abad', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूसरे विश्व-युद्ध का समय था, परंतु हमारी नाभा रियासत का राजा अंग्रेजों ने 1923 में गिरफ़्तार कर लिया था और तमिलनाडु में कोडाईकनाल में ही, जंग शुरू होने से पहले उसका देहांत हो गया था। उस राजा का बेटा, कहते थे अभी विलायत में पढ़ रहा था। इसलिए हमारे देसी रियासत में भी अंग्रेज की ही चलती थी फिर भी राजा के न रहते, अंग्रेज हमारी रियासत के गाँवों से 'जब रन' भर्ती नहीं कर पाया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ee2a8a2f-c833-498d-a754-aa50116e7a3e', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लोगों को फौज में भर्ती करने के लिए जब कुछ अफ़सर आते तो उनके साथ कुछ नौटंकी वाले भी हुआ करते। वे रात को खुले मैदान में शामियाने लगाकर लोगों को फौज के सुख-आराम, बहादुरी के दृश्य दिखाकर आकर्षित किया करते। उनका एक गाना अभी भी याद है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('0a4169e0-46fa-4b0f-a0be-c91065072d92', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भर्ती हो जा रे रंगरूट भर्ती हो जा रे--- अठे मिले सैं टूटे लीतर उठे मिलैंगे बूट, भर्ती हो जा रे, हो जा रे रंगरूट। अठे पहन सैं फटे पुराने उठे मिलेंगे सूट$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('62980de0-13d0-4372-8f44-f847f5e603f1', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भरती हो जा रे, हो जा रे रंगरूट इन्हीं बातों से आकर्षित हो कुछ नौजवान भर्ती के लिए तैयार हो जाया करते। कभी-कभी हमें भी महसूस होता कि हम भी फौजी जवानों से कम नहीं। धोबी की धुली वर्दी और पॉलिश किए बूट और जुराबों को पहने जब हम स्काउटिंग की परेड करते तो लगता हम फौजी ही हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2de51007-d57a-453b-b6ec-19fbc7ef4587', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मास्टर प्रीतमचंद को स्कूल के समय में कभी भी हमने मुस्कुराते या हँसते न देखा था। उनका ठिगना कद, दुबला-पतला परंतु गठीला शरीर, माता के दागों से भरा चेहरा और बाज-सी तेज आँखें, खाकी वर्दी, चमड़े के चौड़े पंजों वाले बूट—सभी कुछ ही भयभीत करने वाला हुआ करता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ac6548f9-833e-4194-b5e6-e1b6927d8c88', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनके बूटों की ऊँची एड़ियों के नीचे भी खुरियाँ लगी रहतीं, जैसे ताँगे के घोड़े के पैरों में लगी रहती हैं। अगले हिस्से में, पंजों के नीचे मोटे सिरों वाले कील ठुके होते। यदि वह सख्त जगह पर भी चलते तो खुरियों और कीलों के निशान वहाँ भी दिखाई देते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0344f421-d832-437a-832f-86194dea64a6', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हम ध्यान से देखते, इतने बड़े और भारी-भारी बूट पहनने के बावजूद उनके टखनों में कहीं मोच तक नहीं आती थी। (उनको देखकर हम यदि घरवालों से बूटों की माँग करते तो माँ-बाप यही कहते कि टखने टेढ़े हो जाएँगे, सारी उमर सीधे न चल पाओगे।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9839c286-d088-4e04-be25-2869fd96de66', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मास्टर प्रीतमचंद से हमारा डरना तो स्वाभाविक था, परंतु हम उनसे नफरत भी करते थे। कारण तो उसका मार-पीट था। हम सभी को (जो मेरी उमर के हैं) वह दिन नहीं भूल पाया जिस दिन वह हमें चौथी श्रेणी में फारसी पढ़ाने लगे थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5dcc765f-6b2b-4471-8bcf-b4ce71507a96', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमें उर्दू का तो तीसरी श्रेणी तक अच्छा अभ्यास हो गया था परंतु फारसी तो अंग्रेजी से भी मुश्किल थी। अभी हमें पढ़ते एक सप्ताह भी न हुआ होगा कि प्रीतमचंद ने हमें एक शब्द-रूप याद करने को कहा और आदेश दिया कि कल इसी घंटी में जुबानी सुनेंगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e6c03047-a3d9-466b-8c1d-69a5e0126c59', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हम सभी घर लौटकर, रात देर तक उसी शब्द-रूप को बार-बार याद करते रहे परंतु केवल दो-तीन ही लड़के थे जिन्हें आधी या कुछ अधिक शब्द-रूप याद हो पाया। दूसरे दिन बारी-बारी सबको सुनाने के लिए कहा तो एक भी लड़का न सुना पाया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('469d5998-bc52-4ec1-8fcb-efa7ca54d3fb', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तभी मास्टर जी गुर्राए—सभी कान पकड़ो। हमने झुककर टाँगों के पीछे से बाँहें निकालकर कान पकड़े तो वह गुस्से से चीखे—पीठ ऊँची करो।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('925965ea-5ee6-4b49-aa6a-73767075ab86', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पीठ ऊँची करके कान पकड़ने से, तीन-चार मिनट में ही टाँगों में जलन होने लगती थी। मेरे जैसे कमजोर तो टाँगों के थकने से कान पकड़े हुए ही गिर पड़ते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ac58f552-19ea-44b1-85fd-21303c8a5d72', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब तक मेरी और हरबंस की बारी आई तब तक हेडमास्टर शर्मा जी अपने दफ्तर में आ चुके थे। जब हमें सजा दी जा रही थी तो उसके कुछ$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4fefa422-5c40-4d66-912f-807c62f8f8de', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुछ दिन पहले शर्मा जी, स्कूल की पूरब की ओर बने सरकारी अस्पताल में डॉक्टर कपलाश से मिलने गए थे। वह दफ्तर के सामने की ओर चले आए। आते ही जो कुछ उन्होंने देखा वह सहन नहीं कर पाए। शायद यह पहला अवसर था कि वह पी.टी. प्रीतमचंद की उस बर्बरता को सहन न कर पाए। बहुत उत्तेजित हो गए थे।—'व्हाट आर यू डूइंग, इज इट दा वे टू पनिश दा स्टूडेंट्स ऑफ फोर्थ क्लास? स्टॉप इट एट वन्स!' हमें तब अंग्रेजी नहीं आती थी, क्योंकि उस समय पाँचवीं श्रेणी से अंग्रेजी पढ़ानी शुरू की जाती थी। परंतु हमारे स्कूल के सातवीं-आठवीं श्रेणी के लड़कों ने बताया था कि शर्मा जी ने कहा था—क्या करते हैं? क्या चौथी श्रेणी को सजा देने का यह ढंग है? इसे फौरन बंद करो। शर्मा जी गुस्से से काँपते बरामदे से ही अपने दफ्तर में चले गए थे। फिर जब प्रीतमचंद कई दिन स्कूल नहीं आए तो यह बात सभी मास्टरों की जुबान पर थी कि हेडमास्टर शर्मा जी ने उन्हें मुअत्तल करके अपनी ओर से आदेश लिखकर, मंजूरी के लिए हमारी रियासत की राजधानी, नाभा भेज दिया है। वहाँ हरझीललाल नाम के 'महकमा-ए-तालीम' के डायरेक्टर थे जिनसे ऐसे आदेश की मंजूरी आवश्यक थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('55e2dd64-b678-44bd-a0c2-a665b79de743', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'ed5cdcf4-7b5f-48d4-bfbc-0a748b49ea54', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुछ दिन पहले शर्मा जी, स्कूल की पूरब की ओर बने सरकारी अस्पताल में डॉक्टर कपलाश से मिलने गए थे। वह दफ्तर के सामने की ओर चले आए। आते ही जो कुछ उन्होंने देखा वह सहन नहीं कर पाए। शायद यह पहला अवसर था कि वह पी.टी. प्रीतमचंद की उस बर्बरता को सहन न कर पाए। बहुत उत्तेजित हो गए थे।—'व्हाट आर यू डूइंग, इज इट दा वे टू पनish दा स्टूडेंट्स ऑफ फोर्थ क्लास? स्टॉप इट एट वन्स!' हमें तब अंग्रेजी नहीं आती थी, क्योंकि उस समय पाँचवीं श्रेणी से अंग्रेजी पढ़ानी शुरू की जाती थी। परंतु हमारे स्कूल के सातवीं-आठवीं श्रेणी के लड़कों ने बताया था कि शर्मा जी ने कहा था—क्या करते हैं? क्या चौथी श्रेणी को सजा देने का यह ढंग है? इसे फौरन बंद करो। शर्मा जी गुस्से से काँपते बरामदे से ही अपने दफ्तर में चले गए थे। फिर जब प्रीतमचंद कई दिन स्कूल नहीं आए तो यह बात सभी मास्टरों की जुबान पर थी कि हेडमास्टर शर्मा जी ने उन्हें मुअत्तल करके अपनी ओर से आदेश लिखकर, मंजूरी के लिए हमारी रियासत की राजधानी, नाभा भेज दिया है। वहाँ हरझीललाल नाम के 'महकमा-ए-तालीम' के डायरेक्टर थे जिनसे ऐसे आदेश की मंजूरी आवश्यक थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-384Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
